export const BODY: string = "\n<p>DPI وPPI هما الثنائي الأكثر خلطًا في عالم الصور كله. الناس يستخدمونهما كأنهما الشيء نفسه، والأدوات توسّمهما بشكل غير متسق، والنتيجة كومة من النصائح الخاطئة.</p>\n<p>للخلط تكاليف حقيقية. المصممون يضعون 300 DPI على صور ويب لا تحتاجه، ومشتري الطباعة يقبلون ملفات 72 DPI لن تُطبع جيدًا أبدًا.</p>\n<p>يفصل هذا المقال المصطلحين بوضوح، ويشرح أين يهم كل منهما، ويعطيك قاعدة بسيطة لتقرر أي رقم تنتبه إليه في أي موقف.</p>\n<h2 id=\"dpi-defined\">DPI معرّف: نقاط الحبر</h2>\n<p>DPI تعني نقاطًا في البوصة وتنتمي إلى الطابعات. تعد نقاط الحبر الصغيرة التي تضعها طابعة في بوصة واحدة من الورق، وتقرر مدى دقة التفاصيل المطبوعة.</p>\n<p>طابعة 300 DPI تستطيع وضع 300 نقطة حبر في البوصة، وطابعة 600 DPI تستطيع وضع ضعف ذلك، ولهذا تستخدم مطبوعات الفن القيمة الأعلى. وفي ملفات الصور، DPI وسام بيانات وصفية يخبر البرنامج كثافة الطباعة المقصودة، ولا يغيّر البكسلات.</p>\n<h2 id=\"ppi-defined\">PPI معرّف: بكسلات على شاشة</h2>\n<p>PPI تعني بكسلات في البوصة وتنتمي إلى الشاشات. تعد كم بكسلًا فيزيائيًا تحشره شاشة في بوصة واحدة من سطحها.</p>\n<p>هاتف بشاشة 400 PPI يحشر 400 بكسل في كل بوصة، ولهذا يبدو النص حادًا حتى بأحجام صغيرة. وشاشة قديمة 96 PPI تعرض النص نفسه بحواف مرئية. وPPI خاصية في عتاد الشاشة لا في ملف الصورة، فلا تستطيع تغيير PPI شاشة بتحرير ملف.</p>\n<h2 id=\"why-they-get-confused\">لماذا يُخلط بين DPI وPPI</h2>\n<p>للخلط ثلاثة أسباب. أولًا، المصطلحان يبدوان متشابهين وكلاهما يتضمن بوصات. ثانيًا، بعض البرامج تستخدمهما كمرادفين لنفس وسام الملف. ثالثًا، كلاهما يتعلق بالكثافة.</p>\n<p>فوتوشوب مثلًا يوسّم حقل دقة الملف PPI، بينما المطبعة تسمي الرقم نفسه DPI. الملف فيه رقم واحد وصناعتان تعطيانه اسمين. والحل العملي هو السؤال عما يتحكم فيه الرقم: إذا تحكم في الحبر على الورق ففكر DPI، وإذا تحكم في البكسلات على شاشة ففكر PPI.</p>\n<h2 id=\"print-what-matters\">الطباعة: ما يهم هو DPI</h2>\n<p>في الطباعة، DPI يقرر كل شيء عن الحدة. صورة 3000 بكسل مطبوعة بـ300 DPI تغطي 10 بوصات، بينما نفس البكسلات بـ150 DPI تغطي 20 بوصة بنصف الكثافة.</p>\n<p>معيار الطباعة هو 300 DPI لأي شيء يُحمل في اليد: كتب وكتيبات ومجلات وتغليف. وبهذه الكثافة لا تستطيع العين تمييز النقاط الفردية من مسافة قراءة عادية. والمطبوعات الكبيرة ترخي القاعدة: ملصق يُرى من مترين يبدو جيدًا بـ150 DPI، ولوحة إعلانات تُرى من الطريق قد تنزل إلى 50 DPI أو أقل دون أن يلاحظ أحد.</p>\n<h2 id=\"web-what-matters\">الويب: البكسلات تهم وDPI لا يهم</h2>\n<p>على الويب، تتجاهل المتصفحات وسام DPI تمامًا. تعرض الصورة بكسلًا ببكسل، فصورة 1000 بكسل تشغل 1000 بكسل شاشة سواء قال وسامها 72 أو 300.</p>\n<p>ما يهم على الويب هو أبعاد البكسل بالنسبة لحجم العرض. صورة معروضة بعرض 800 بكسل يجب أن تحمل بين 800 و1600 بكسل في الملف، حسب كثافة الشاشة. ووضع 300 DPI على صورة ويب لا يغيّر شيئًا في مظهرها أو تحميلها. والقاعدة بسيطة: طابق الأبعاد مع العرض واضغط الملف ليكون سريعًا وانسَ DPI حتى تذهب الصورة إلى الطباعة.</p>\n<h2 id=\"the-72-dpi-myth\">أسطورة 72 DPI</h2>\n<p>الأسطورة الأكثر استمرارًا في عالم الصور هي أن صور الويب يجب أن تكون 72 DPI. تأتي من أول ماكنتوش، التي عرضت شاشتها 72 بكسلًا في البوصة، وبقيت خاطئة لعقود.</p>\n<p>الشاشات الحديثة تتراوح من 100 إلى أكثر من 400 PPI، فلا قيمة DPI واحدة تصفها كلها. وسام 72 DPI على صورة ويب حادث تاريخي لا متطلب. والأسطورة تنجو لأن البرامج ما زالت تكتب 72 في الملفات افتراضيًا: الكاميرات ولقطات الشاشة والصادرات توسّم 72 DPI عندما لا تملك قيمة أفضل.</p>\n<h2 id=\"the-300-dpi-standard\">معيار 300 DPI للطباعة</h2>\n<p>معيار 300 DPI موجود بسبب حدود العين البشرية. من مسافة قراءة عادية، لا تستطيع العين تمييز تفاصيل أدق من نحو 300 نقطة في البوصة، فالكثافة الأعلى لا تضيف شيئًا.</p>\n<p>ولهذا تطلب مطابع الكتب والمجلات وشركات التغليف 300. إنها النقطة التي تتوقف عندها الجودة عن التحسن لمطبوعة تُحمل في اليد، وطلب المزيد يضخم الملف فقط. والفن وعمل الأرشيف يصل إلى 600 DPI لأن تلك المطبوعات تُفحص عن قرب، أحيانًا بتكبير.</p>\n<h2 id=\"screens-and-retina\">الشاشات وريتينا وPPI</h2>\n<p>شاشات ريتينا وعالية الكثافة غيّرت حساب الويب. هاتف بشاشة 2x يستخدم بكسلين فيزيائيين لكل بكسل CSS، فالصورة تحتاج ضعف البكسلات لتبقى حادة.</p>\n<p>هذا تأثير PPI لا تأثير DPI. الشاشة تحشر بكسلات أكثر في البوصة، فيجب أن يحمل ملف الصورة بكسلات أكثر في بوصة الشاشة لمواكبتها. والإجابة العملية هي تقديم الصور بضعف حجم العرض: صورة معروضة بعرض 400 بكسل CSS يجب أن تحمل نحو 800 بكسل في الملف، فتبدو حادة على شاشات ريتينا والعادية معًا.</p>\n<h2 id=\"print-size-math\">حساب حجم الطباعة: البكسلات مقسومة على DPI</h2>\n<p>صيغة حجم الطباعة قسمة: العرض بالبكسل مقسومًا على DPI يساوي العرض المطبوع بالبوصات. صورة 3000 بكسل بـ300 DPI تُطبع بعرض 10 بوصات.</p>\n<p>اعمل عكسيًا من الحجم الذي تحتاجه. طباعة 8 في 10 بوصات بـ300 DPI تحتاج 2400 في 3000 بكسل، فأي ملف أصغر من ذلك سيُطبع ناعمًا عند ذلك الحجم. وPPI لا يدخل هذه الصيغة أبدًا. واستخدم <a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصورة</a> لتأكيد عدد البكسلات، ثم <a href=\"/ar/taghyir-dpi-as-sura/\">مغير DPI</a> لتثبيت الوسام.</p>\n<h2 id=\"metadata-vs-pixels\">البيانات الوصفية مقابل البكسلات: التمييز المركزي</h2>\n<p>وسام DPI بيانات وصفية: بايتات قليلة في ترويسة الملف تصف كثافة الطباعة المقصودة. تغييره يعيد كتابة تلك البايتات ويترك كل بكسل سليمًا.</p>\n<p>أما PPI فعتاد: الكثافة الفيزيائية لشاشة. لا يمكن تغييره بتحرير ملف، لأنه يصف جهاز العرض لا الصورة. وهذا التمييز يشرح لماذا تكون تغييرات DPI دون فقدان جودة وفورية، بينما تغييرات PPI مستحيلة. فأحدهما وسام في الملف والآخر حقيقة عن شاشة.</p>\n<h2 id=\"when-to-change-dpi\">متى تغيّر DPI</h2>\n<p>غيّر DPI عندما يطلبه سير عمل طباعة. منصات الكتب والمجلات والمطابع تراجع الوسام، والملف بالقيمة الخاطئة يُرفض قبل أن ينظر إليه أحد.</p>\n<p>وغيّر DPI عندما يكون الوسام مفقودًا. صورة بلا قيمة DPI تترك حجم الطباعة غير معرّف، والبرنامج الذي يفتحها سيخمّن، وغالبًا بشكل خاطئ. وغيّر DPI عندما تعيد استخدام صورة شاشة للطباعة، فصورة موسومة بـ300 DPI ترضي سير الطباعة، بشرط أن تكفي بكسلاتها للحجم الذي تحتاجه.</p>\n<h2 id=\"when-dpi-does-not-help\">متى لا يساعد DPI</h2>\n<p>لا يساعد DPI عندما تكون البكسلات قليلة جدًا. صورة مصغرة 400 في 400 موسومة بـ300 DPI تبقى صورة مصغرة 400 في 400، وتُطبع بعرض أكثر قليلًا من بوصة واحدة.</p>\n<p>ولا يساعد DPI صورة ضبابية. الضبابية تعيش في البكسلات، ولا تحرير بيانات وصفية يستطيع تركيز صورة غير مركزة أو لقطة مهتزة. ولا يساعد DPI على الشاشات، فالمتصفح يتجاهل الوسام. ولا يساعد أيضًا في حجم الملف، فالوسام بايتات قليلة.</p>\n<h2 id=\"workflow-for-print\">سير عمل طباعة يقوم به صحيحًا</h2>\n<p>ابدأ بالحجم الفيزيائي الذي تحتاجه بالبوصات. اضرب في 300 للحصول على البكسلات التي تحتاجها، وتأكد بفاحص الأبعاد أن ملفك يفي بذلك العدد.</p>\n<p>ثبت وسام DPI على 300 بمغير DPI، وابحث عن شارة DPI المتحقق منه. الشارة تؤكد أن الوسام حُفظ صحيحًا وسيُقرأ نفسه في أي برنامج. وأرسل طبعة تجريبية أو بروفة قبل الطبعة الكاملة، فالبروفة تكتشف مشاكل لا تستطيع الأرقام كشفها، مثل ألوان تتغير على الورق.</p>\n<h2 id=\"workflow-for-web\">سير عمل ويب يتجاهل DPI</h2>\n<p>ابدأ بحجم العرض ببكسلات CSS. ضاعفه لشاشات ريتينا، وهذا الرقم المضاعف هو عرض البكسل الذي يحتاجه ملفك.</p>\n<p>اضغط الملف حتى يصبح فقدان الجودة بالكاد ملحوظًا، ثم تراجع خطوة. هذا هو أصغر ملف ما زال يبدو جيدًا، وهو الذي سيشكرك عليه زوارك. وراجع الأبعاد بالفاحص والوزن بالضاغط. هذان الرقمان لا DPI يقرران هل الصورة مناسبة للويب.</p>\n<h2 id=\"quick-reference\">مرجع سريع: DPI مقابل PPI</h2>\n<p>DPI نقاط في البوصة، مفهوم طباعة. يعيش في الملف كوسام بيانات وصفية ويقرر حجم الطباعة، وتغيّره بمغير DPI عندما يطلبه سير طباعة.</p>\n<p>أما PPI فبكسلات في البوصة، مفهوم شاشة. يصف عتاد الشاشة ويقرر مدى حدة مظهر الشاشة، ولا تستطيع تغييره بتحرير ملف. وعلى الويب، اهتم بأبعاد البكسل وحجم الملف. وفي الطباعة، اهتم بأبعاد البكسل ووسام DPI.</p>\n<p>للأدوات العملية، راجع <a href=\"/ar/blog/dalil-mughayyir-dpi-as-suwar/\">مغير DPI للصور: الدليل الكامل</a> والخطوات في <a href=\"/ar/blog/kayfiyya-taghyir-dpi-as-sura/\">كيف تغيّر DPI صورة</a>. وللأرقام ذات الصلة، اقرأ <a href=\"/ar/blog/al-abad-vs-al-diqqa-vs-hajm-al-malaf/\">الأبعاد مقابل الدقة مقابل حجم الملف</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل DPI هو نفسه PPI؟","answer":"لا، رغم أن بعض البرامج تستخدم الوسمين كأنهما الشيء نفسه لنفس وسام الملف. DPI يعد نقاط حبر في البوصة على ورق، بينما PPI يعد بكسلات فيزيائية في البوصة على شاشة. السياق يقرر أي معنى ينطبق."},{"question":"هل صورة 300 DPI تبدو أفضل على موقع من صورة 72 DPI؟","answer":"لا، المتصفحات تتجاهل وسام DPI وتعرض الصورة بكسلًا ببكسل، فالملفان يبدوان متطابقين على الشاشة. حدة الويب تأتي من أبعاد البكسل لا من قيمة DPI."},{"question":"لماذا تطلب المطابع 300 DPI بينما الشاشات تستخدم 72 DPI؟","answer":"الطباعة والشاشات وسيطان مختلفان باحتياجات كثافة مختلفة. من مسافة قراءة، تميز العين نحو 300 نقطة في البوصة على ورق، فالطباعة تحتاج تلك الكثافة لتبدو حادة. أما الشاشات فتعرض البكسلات مباشرة، فالوسام لا يهم."},{"question":"هل يمكنني تحويل صورة شاشة منخفضة PPI إلى صورة طباعة عالية DPI؟","answer":"فقط بمعنى البيانات الوصفية: يمكنك وضع وسام 300 DPI على أي صورة، لكن الوسام لا يضيف بكسلات. لقطة ببكسلات قليلة ستُطبع صغيرة بـ300 DPI. الجودة الحقيقية تأتي من عدد البكسلات لا من الوسام."},{"question":"أي PPI يجب أن تحمل صور هاتفي للطباعة؟","answer":"صور الهاتف ليس لها PPI بمعنى الطباعة؛ لها أبعاد بكسل وغالبًا لا وسام DPI. اقسم العرض بالبكسل على 300 لتجد عرض الطباعة بالبوصات، ثم قرر هل يكفي الحجم الذي تحتاجه."},{"question":"هل يجب أن أقلق بشأن DPI لرفع وسائل التواصل؟","answer":"لا، منصات التواصل تعرض الصور على شاشات، حيث تهم أبعاد البكسل وحجم الملف فقط. ارفع الأبعاد الصحيحة وملفًا مضغوطًا بشكل معقول، وتجاهل DPI تمامًا."}];
